*#define CHECK

* SquaredME.F
* assembly of squared matrix element
* generated by FormCalc 6 Aug 2012 0:33

	subroutine P1SquaredME(result, qext, flags)
	use global_vars
	implicit none
	double complex result(*)
	double complex amp1(1)
	integer nlegs, flags
        parameter (nlegs = 6)
        double precision qext(nlegs,4)
        integer i, j

#include "vars.h"

	double precision P1sumup
	external P1sumup

	integer Hel1, Hel2, Hel3, Hel4, Hel5, Hel6, Hel7, Hel8
	equivalence (Hel(1), Hel1)
	equivalence (Hel(2), Hel2)
	equivalence (Hel(3), Hel3)
	equivalence (Hel(4), Hel4)
	equivalence (Hel(5), Hel5)
	equivalence (Hel(6), Hel6)
	equivalence (Hel(7), Hel7)
	equivalence (Hel(8), Hel8)

        integer nSUNtree
        parameter (nSUNtree = 1)
        double complex Ctree1(nSUNtree), CtreeVV(nSUNtree), temp
        double complex ampW, ampWm
        double precision S34, S56

c        print*,'from SquaredME LEGSX:', LEGSX, LEGS

	S = SInvariant(1,2)

	T = TInvariant(1,3)

	U = TInvariant(2,3)

C Note: qext(6,4) are the true qq -> 4l momenta
	S34 = qext(3,1)*qext(4,1) - qext(3,2)*qext(4,2) 
     &  - qext(3,3)*qext(4,3) - qext(3,4)*qext(4,4)
        S34 = S34*2
	S56 = qext(5,1)*qext(6,1) - qext(5,2)*qext(6,2) 
     &  - qext(5,3)*qext(6,3) - qext(5,4)*qext(6,4)
        S56 = S56*2

c	call P1abbr0_s

	result(1) = 0
	result(2) = 0

***[sum over quark helicities
       if (flags.eq.12) then
        i = -1
        j = +1
       else if (flags.eq.11) then
        i = -1
        j = -1
       else if (flags.eq.22) then
        i = +1
        j = +1
       else if (flags.eq.21) then
        i = +1
        j = -1
       else
        print*,"wrong flags in P1SquaredME(), flags =",flags
        stop
       endif
       
       do Hel2 = -1, 1, 2 ! photon 2

	Hel5 = 1 ! e+
	Hel6 = -Hel5 ! nu_e

	Hel7 = -1 ! mu-
	Hel8 = -Hel7 ! mu+
	
!!![amp_i
       Hel1 = i  ! photon 1

***[for qq->W+V*Br(W+)*Br(V)
c#ifdef NINH_DECAY
        Ctree1(1) = 0

        do Hel3 = hel_W_min, hel_W_max, hel_W_step ! for V1
        do Hel4 = hel_Z_min, hel_Z_max, hel_Z_step ! for V2        
        
	call P1abbr0_hel
	Ctree(1) = 0
	call P1born
        CtreeVV(1) = Ctree(1)

        call P1decayWll(ampW, 3, 5, 6)
        call P1decayWmll(ampWm, 4, 7, 8)

c         ampW = 1
c         ampZ = 1 ! Ninh check
c          print*,"hel 5678", Hel5, Hel6, Hel7, Hel8, ampW, ampZ

        temp = -CtreeVV(1)*ampW*ampWm
     &  /((S34 - CMWsq)*(S56 - CMWsq))

        Ctree1(1) = Ctree1(1) + temp

        enddo
        enddo
c#endif
***]for qq->W+V*Br(W+)*Br(V)
       amp1(1) = Ctree1(1)
!!!]amp_i

!!![amp_j
	if ( j .ne. i ) then
	Hel1 = j ! photon 1
c	Ctree(1) = 0
c	call P1abbr0_hel
c	call P1born
***[for qq->W+V*Br(W+)*Br(V)
c#ifdef NINH_DECAY
        Ctree1(1) = 0

        do Hel3 = hel_W_min, hel_W_max, hel_W_step ! for V1
        do Hel4 = hel_Z_min, hel_Z_max, hel_Z_step ! for V2        
        
	call P1abbr0_hel
	Ctree(1) = 0
	call P1born
        CtreeVV(1) = Ctree(1)

        call P1decayWll(ampW, 3, 5, 6)
        call P1decayWmll(ampWm, 4, 7, 8)

c         ampW = 1
c         ampZ = 1 ! Ninh check
c          print*,"hel 5678", Hel5, Hel6, Hel7, Hel8, ampW, ampZ

        temp = -CtreeVV(1)*ampW*ampWm
     &  /((S34 - CMWsq)*(S56 - CMWsq))

        Ctree1(1) = Ctree1(1) + temp

        enddo
        enddo
c#endif
***]for qq->W+V*Br(W+)*Br(V)
	endif
!!!]amp_j

	result(1) = result(1) + P1sumup(amp1(1), Ctree1)
	enddo
***]sum over quark helicities

#ifdef CHECK
	print *, 'S =', S
	print *, 'T =', T
	print *, 'U =', U
	print *, 'S56 =', S56
	print *, 'S34 =', S34

	print *, 'tree =', result(1)
	print *, 'loop =', result(2)
	stop
#endif
	end


************************************************************************

	double precision function P1sumup(CCloop, CCtree)
	implicit none

#include "vars.h"

	double complex CCloop(1), CCtree(1)
	double complex m

	P1sumup = 0

	m = 0
	m = m + CCloop(1)*1
	P1sumup = P1sumup + DBLE(DCONJG(CCtree(1))*m)
	end
